-- JobHunt / huntjob MySQL -> Supabase PostgreSQL
-- Converted from the uploaded huntjob MySQL export.
-- Existing records are included.
--
-- IMPORTANT:
-- 1. Run this in Supabase SQL Editor only if the target tables are empty/new.
-- 2. This migration preserves the original camelCase column names.
-- 3. MySQL ENUMs are represented as VARCHAR because Sequelize already enforces
--    the allowed values in the application models.
-- 4. Foreign keys are added after all data is inserted.

BEGIN;

DROP TABLE IF EXISTS "documents", "notifications", "savedjobs", "applications", "auditlogs", "jobs", "users" CASCADE;

CREATE TABLE "users" (
  "id" UUID NOT NULL,
  "email" VARCHAR(255) NOT NULL,
  "password" VARCHAR(255) NOT NULL,
  "firstName" VARCHAR(255) NOT NULL,
  "lastName" VARCHAR(255) NOT NULL,
  "middleName" VARCHAR(255),
  "contactNumber" VARCHAR(255),
  "address" TEXT,
  "barangay" VARCHAR(255),
  "dateOfBirth" TIMESTAMP,
  "gender" VARCHAR(20),
  "userType" VARCHAR(30) DEFAULT 'applicant',
  "department" VARCHAR(255),
  "isActive" BOOLEAN DEFAULT TRUE,
  "isVerified" BOOLEAN DEFAULT FALSE,
  "lastLogin" TIMESTAMP,
  "resetToken" VARCHAR(255),
  "resetTokenExpiry" TIMESTAMP,
  "profilePhoto" VARCHAR(255),
  "createdAt" TIMESTAMP,
  "updatedAt" TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("email")
);

CREATE TABLE "jobs" (
  "id" UUID NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "department" VARCHAR(255) NOT NULL,
  "description" TEXT NOT NULL,
  "requirements" TEXT,
  "salaryRange" VARCHAR(255),
  "employmentType" VARCHAR(30) DEFAULT 'Full-time',
  "positions" INTEGER DEFAULT 1,
  "deadline" TIMESTAMP,
  "status" VARCHAR(20) DEFAULT 'open',
  "requiredDocuments" TEXT,
  "postedBy" UUID NOT NULL,
  "viewCount" INTEGER DEFAULT 0,
  "category" VARCHAR(255),
  "isActive" BOOLEAN DEFAULT TRUE,
  "createdAt" TIMESTAMP,
  "updatedAt" TIMESTAMP,
  "employerId" UUID,
  "municipality" VARCHAR(255),
  PRIMARY KEY ("id")
);

CREATE TABLE "applications" (
  "id" UUID NOT NULL,
  "jobId" UUID NOT NULL,
  "userId" UUID NOT NULL,
  "status" VARCHAR(30) DEFAULT 'submitted',
  "coverLetter" TEXT,
  "rating" INTEGER,
  "hrNotes" TEXT,
  "managerNotes" TEXT,
  "reviewedBy" UUID,
  "reviewedAt" TIMESTAMP,
  "interviewDate" TIMESTAMP,
  "declaration" BOOLEAN DEFAULT FALSE,
  "createdAt" TIMESTAMP,
  "updatedAt" TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "documents" (
  "id" UUID NOT NULL,
  "applicationId" UUID NOT NULL,
  "documentType" VARCHAR(255) NOT NULL,
  "fileName" VARCHAR(255) NOT NULL,
  "filePath" VARCHAR(255) NOT NULL,
  "fileSize" INTEGER,
  "mimeType" VARCHAR(255),
  "uploadedAt" TIMESTAMP,
  "userId" UUID,
  PRIMARY KEY ("id")
);

CREATE TABLE "notifications" (
  "id" UUID NOT NULL,
  "userId" UUID NOT NULL,
  "type" VARCHAR(40) NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "message" TEXT NOT NULL,
  "relatedId" UUID,
  "relatedType" VARCHAR(255),
  "isRead" BOOLEAN DEFAULT FALSE,
  "readAt" TIMESTAMP,
  "metadata" JSONB,
  "createdAt" TIMESTAMP,
  "updatedAt" TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "savedjobs" (
  "id" UUID NOT NULL,
  "userId" UUID NOT NULL,
  "jobId" UUID NOT NULL,
  "savedAt" TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "auditlogs" (
  "id" UUID NOT NULL,
  "userId" UUID,
  "action" VARCHAR(255) NOT NULL,
  "entityType" VARCHAR(255),
  "entityId" UUID,
  "ipAddress" VARCHAR(255),
  "userAgent" VARCHAR(255),
  "metadata" JSONB,
  "createdAt" TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE INDEX "applications_jobId_idx" ON "applications" ("jobId");
CREATE INDEX "applications_userId_idx" ON "applications" ("userId");
CREATE INDEX "applications_reviewedBy_idx" ON "applications" ("reviewedBy");
CREATE INDEX "auditlogs_userId_idx" ON "auditlogs" ("userId");
CREATE INDEX "documents_applicationId_idx" ON "documents" ("applicationId");
CREATE INDEX "documents_userId_idx" ON "documents" ("userId");
CREATE INDEX "jobs_postedBy_idx" ON "jobs" ("postedBy");
CREATE INDEX "jobs_employerId_idx" ON "jobs" ("employerId");
CREATE INDEX "notifications_userId_isRead_idx" ON "notifications" ("userId", "isRead");
CREATE INDEX "savedjobs_userId_idx" ON "savedjobs" ("userId");
CREATE INDEX "savedjobs_jobId_idx" ON "savedjobs" ("jobId");







ALTER TABLE "applications"
  ADD CONSTRAINT "applications_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "jobs" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  ADD CONSTRAINT "applications_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  ADD CONSTRAINT "applications_reviewedBy_fkey" FOREIGN KEY ("reviewedBy") REFERENCES "users" ("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "auditlogs"
  ADD CONSTRAINT "auditlogs_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users" ("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "documents"
  ADD CONSTRAINT "documents_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "applications" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  ADD CONSTRAINT "documents_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users" ("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "jobs"
  ADD CONSTRAINT "jobs_postedBy_fkey" FOREIGN KEY ("postedBy") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  ADD CONSTRAINT "jobs_employerId_fkey" FOREIGN KEY ("employerId") REFERENCES "users" ("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "notifications"
  ADD CONSTRAINT "notifications_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "savedjobs"
  ADD CONSTRAINT "savedjobs_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
  ADD CONSTRAINT "savedjobs_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "jobs" ("id") ON DELETE CASCADE ON UPDATE CASCADE;

COMMIT;

